-- 0001_init.sql: the complete Phase 1 schema of the hosted multi-club service.
--
-- Conventions (see docs/phase1/conventions.md for the full list):
--   * Every surrogate key is `bigint GENERATED BY DEFAULT AS IDENTITY`. BY DEFAULT
--     (not ALWAYS) lets the legacy importer (#38) insert explicit ids; it then
--     calls setval() on each sequence. Ids are exposed to clients as JSON numbers.
--   * Importer id strategy: legacy integer ids are KEPT for users, shelf_entries,
--     posts (from book_posts), quotes, club_picks, milestones, next_up_votes,
--     next_up_nominations, events, search_history and club_invites. That keeps
--     physical_shelf_layouts.layout (shelf entry ids), `#entry-<id>` links and
--     the id-ordered feeds valid without rewriting. Work ids are NOT kept: legacy
--     books map onto works through legacy_work_keys (several books can merge into
--     one work, and the catalog may already hold harvested works). The importer
--     calls setval() on posts right after the kept book_posts ids and before it
--     inserts the few unmirrored legacy pick notes, which get new ids.
--   * Enumerations are `text` + CHECK, never Postgres enums: values sort as text
--     (GET /api/shelf orders statuses alphabetically, as the legacy app did) and
--     adding a value is a one-line migration.
--   * Every timestamp is timestamptz (UTC). The app never relies on the server's
--     TimeZone setting.
--   * Length limits count characters (char_length), matching Python len().
--   * Usernames, slugs and invite codes are stored normalised (lowercase or
--     uppercase), so plain unique indexes are case-insensitive by construction;
--     verified emails get a unique index on lower(email). Those columns use
--     COLLATE "C" so ORDER BY matches the legacy byte order (digits < '_' < letters).
--   * ON DELETE rules: personal data CASCADEs with its user; club data CASCADEs
--     with its club; references from personal or club data into the catalog are
--     RESTRICT (a catalog merge re-points rows first, nothing is ever lost because
--     of a catalog operation); "who did it" references to users are SET NULL
--     where the row must outlive the account.
--   * Club-scoped tables carry club_id, and child rows reference their parent
--     through (club_id, parent_id) composite keys, so a row can never point into
--     another club. Reasoned deviations from the #37 wording "club-scoped tables
--     carry club_id, personal tables don't" (recorded in #37 and the parity
--     checklist):
--       - posts and events hold both scopes in one table (club_id NULL =
--         personal). A reply is tied to its parent's work AND scope by the
--         composite FK posts_parent_fk on (parent_id, work_id, scope_key), and a
--         personal event can never carry a pick (events_personal_no_pick).
--       - post_reactions has no club_id: a reaction inherits its scope through
--         post_id (ON DELETE CASCADE), so it can never outlive or leave its post.
--   * Not designed yet, room left: Phase 3 friendships (only bc_can_see_user and
--     bc_visible_owners change), Phase 4 device tokens (a push_devices table that
--     references sessions.id ON DELETE CASCADE; the notify_* prefs and
--     club_picks.reminder_sent_at are already here).

CREATE EXTENSION IF NOT EXISTS pg_trgm;
CREATE EXTENSION IF NOT EXISTS unaccent;

-- unaccent() is only STABLE (it reads a dictionary), so it cannot be used in a
-- generated column or an index expression. This wrapper pins the dictionary and
-- is declared IMMUTABLE, the standard workaround.
CREATE FUNCTION bc_unaccent(value text) RETURNS text
    LANGUAGE sql IMMUTABLE PARALLEL SAFE STRICT
    RETURN public.unaccent('public.unaccent'::regdictionary, value);

-- The one expression behind the trigram index on works. Catalog queries must use
-- exactly this function (e.g. `bc_search_text(w.title, w.author_names,
-- w.search_extra) ILIKE ...`) or the index is not used.
CREATE FUNCTION bc_search_text(title text, author_names text, search_extra text) RETURNS text
    LANGUAGE sql IMMUTABLE PARALLEL SAFE STRICT
    RETURN lower(bc_unaccent(title || ' ' || author_names || ' ' || search_extra));

------------------------------------------------------------------------------
-- Accounts (#39)
------------------------------------------------------------------------------

CREATE TABLE users (
    id                        bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    username                  text COLLATE "C" NOT NULL
                              CONSTRAINT users_username_format CHECK (username ~ '^[a-z0-9_]{2,32}$'),
    email                     text NULL
                              CONSTRAINT users_email_format
                              CHECK (email IS NULL OR (char_length(email) <= 254 AND email ~ '^[^@[:space:]]+@[^@[:space:]]+$')),
    email_verified_at         timestamptz NULL,
    email_prompt_dismissed_at timestamptz NULL,
    password_hash             text NOT NULL,
    password_changed_at       timestamptz NOT NULL DEFAULT now(),
    is_admin                  boolean NOT NULL DEFAULT false,
    theme                     text NOT NULL DEFAULT 'paper'
                              CHECK (theme IN ('paper', 'slate', 'forest', 'ink')),
    color_mode                text NOT NULL DEFAULT 'system'
                              CHECK (color_mode IN ('light', 'dark', 'system')),
    locale                    text NOT NULL DEFAULT 'en'
                              CHECK (locale IN ('en', 'de')),
    timezone                  text NOT NULL DEFAULT 'UTC'
                              CHECK (char_length(timezone) BETWEEN 1 AND 64),
    notify_meeting            boolean NOT NULL DEFAULT true,
    notify_pick               boolean NOT NULL DEFAULT true,
    notify_note               boolean NOT NULL DEFAULT true,
    avatar_media_id           bigint NULL,   -- FK added below, after media exists
    created_at                timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT users_verified_needs_email CHECK (email_verified_at IS NULL OR email IS NOT NULL)
);
CREATE UNIQUE INDEX users_username_key ON users (username);
-- Only VERIFIED addresses are unique. An unverified address is never used for
-- login or reset, so nobody can squat another person's address by typing it in.
CREATE UNIQUE INDEX users_verified_email_key ON users (lower(email)) WHERE email_verified_at IS NOT NULL;

COMMENT ON COLUMN users.username IS
    'Login name, display name and URL key. Always lowercase; normalised (trim + lowercase) before every lookup.';
COMMENT ON COLUMN users.email IS
    'The account address. Verified (email_verified_at set): unique, used for login by email and for password reset. Unverified: the address a sign-up or first email change entered; not unique, never used for login or reset. A verified account that changes its address keeps this value until the new one (stored on the open verify_email token) is verified. NULL for accounts imported from the legacy instance until the user adds one.';
COMMENT ON COLUMN users.email_prompt_dismissed_at IS
    'Set when an imported user skips the one-time "add your email" prompt; the prompt is shown while email IS NULL AND this IS NULL.';
COMMENT ON COLUMN users.password_hash IS
    'argon2 PHC string. Legacy hashes from argon2-cffi are copied byte for byte and verify with the parameters stored in the string.';
COMMENT ON COLUMN users.password_changed_at IS
    'Bumped on password change and reset; other sessions are deleted at the same moment.';
COMMENT ON COLUMN users.is_admin IS
    'Instance admin (Rafael): admin queue, takedowns, sign-up invites. Unrelated to club roles.';
COMMENT ON COLUMN users.timezone IS
    'IANA zone for personal dates: shelf finished_on (stored as 12:00 local), "today" checks, personal labels. Validated by the app.';
COMMENT ON COLUMN users.notify_meeting IS
    'Push preference kept for Phase 4 (push is not delivered in Phase 1). Global per user.';

-- Server-side sessions: cookie sessions for the web and bearer tokens for the
-- apps live in one table. Only a SHA-256 of the random secret is stored.
CREATE TABLE sessions (
    id           bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id      bigint NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    kind         text NOT NULL CHECK (kind IN ('cookie', 'bearer')),
    token_hash   bytea NOT NULL CHECK (octet_length(token_hash) = 32),
    label        text NOT NULL DEFAULT '' CHECK (char_length(label) <= 200),
    created_at   timestamptz NOT NULL DEFAULT now(),
    last_used_at timestamptz NOT NULL DEFAULT now(),
    expires_at   timestamptz NOT NULL
);
CREATE UNIQUE INDEX sessions_token_hash_key ON sessions (token_hash);
CREATE INDEX sessions_user_id_idx ON sessions (user_id);
CREATE INDEX sessions_expires_at_idx ON sessions (expires_at);

COMMENT ON COLUMN sessions.token_hash IS
    'SHA-256 of the 32-byte random token. The token itself (cookie value, or bearer "bc_..." string) is never stored.';
COMMENT ON COLUMN sessions.label IS
    'Device label shown in the session list: truncated User-Agent for cookies, the label the app sent for bearer tokens.';
COMMENT ON COLUMN sessions.expires_at IS
    'Sliding idle expiry: pushed to last_used_at + 30 days (cookie) or + 90 days (bearer) when the session is used.';

-- One-time links sent by email. The address is stored on the token because
-- an email change only takes effect once the new address is verified.
CREATE TABLE email_tokens (
    id         bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id    bigint NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    purpose    text NOT NULL CHECK (purpose IN ('verify_email', 'reset_password')),
    email      text NOT NULL CHECK (char_length(email) <= 254),
    token_hash bytea NOT NULL CHECK (octet_length(token_hash) = 32),
    created_at timestamptz NOT NULL DEFAULT now(),
    expires_at timestamptz NOT NULL,
    used_at    timestamptz NULL
);
CREATE UNIQUE INDEX email_tokens_token_hash_key ON email_tokens (token_hash);
CREATE INDEX email_tokens_user_id_idx ON email_tokens (user_id, purpose);

COMMENT ON TABLE email_tokens IS
    'At most one open (used_at NULL, not expired) verify_email token per user: every new one marks the older ones used. Every open reset_password token is marked used by a password change, a reset, an email change and a successful verification.';
COMMENT ON COLUMN email_tokens.email IS
    'verify_email: the address being verified (becomes users.email on success). reset_password: the address the link went to; confirm requires it to equal the current verified users.email.';

------------------------------------------------------------------------------
-- Media store (#43): covers and avatars. Bytes live in the MediaStore
-- (filesystem now, S3 later); this table holds the references.
------------------------------------------------------------------------------

CREATE TABLE media (
    id             bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    public_id      text COLLATE "C" NOT NULL CHECK (public_id ~ '^[a-z0-9]{26}$'),
    kind           text NOT NULL CHECK (kind IN ('avatar', 'cover')),
    source         text NOT NULL CHECK (source IN ('upload', 'openlibrary', 'legacy')),
    ol_cover_id    bigint NULL CHECK (ol_cover_id > 0),
    storage_key    text NULL,
    content_type   text NULL CHECK (content_type IN ('image/webp', 'image/jpeg')),
    variants       text[] NOT NULL DEFAULT '{}',
    width          integer NULL CHECK (width > 0),
    height         integer NULL CHECK (height > 0),
    byte_size      bigint NULL CHECK (byte_size >= 0),
    sha256         bytea NULL CHECK (sha256 IS NULL OR octet_length(sha256) = 32),
    dominant_color text NULL CHECK (dominant_color IS NULL OR dominant_color = '' OR dominant_color ~ '^#[0-9a-f]{6}$'),
    uploaded_by    bigint NULL REFERENCES users (id) ON DELETE SET NULL,
    fetch_failed_at timestamptz NULL,
    removed_at     timestamptz NULL,
    created_at     timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT media_ol_source CHECK ((source = 'openlibrary') = (ol_cover_id IS NOT NULL)),
    CONSTRAINT media_ol_covers_only CHECK (source <> 'openlibrary' OR kind = 'cover'),
    CONSTRAINT media_stored_has_type CHECK (storage_key IS NULL OR content_type IS NOT NULL)
);
CREATE UNIQUE INDEX media_public_id_key ON media (public_id);
CREATE UNIQUE INDEX media_ol_cover_id_key ON media (ol_cover_id) WHERE ol_cover_id IS NOT NULL;
CREATE INDEX media_uploaded_by_idx ON media (uploaded_by) WHERE uploaded_by IS NOT NULL;
CREATE INDEX media_removed_sha256_idx ON media (sha256) WHERE removed_at IS NOT NULL AND sha256 IS NOT NULL;

COMMENT ON COLUMN media.public_id IS
    '26 random base32 characters; the URL key (/media/{public_id}/{variant}). Unguessable, and immutable: replacing an image creates a new row, so responses can be cached forever.';
COMMENT ON COLUMN media.ol_cover_id IS
    'Open Library cover id for source=openlibrary (always > 0; the importer maps legacy cover ids <= 0 to "no cover"). The row exists as soon as a work references the cover; bytes are fetched by cover id on the first request and then served from our domain. A removed row is never attached again (ingest::ol_cover_media returns None for it).';
COMMENT ON COLUMN media.storage_key IS
    'Key prefix in the MediaStore (media::shared::storage_prefix); object keys are <prefix>/<variant>. NULL means the bytes are not stored: not fetched yet (Open Library covers) or removed. removed_at, not storage_key, decides whether a row may be fetched, served or attached: code checks removed_at first.';
COMMENT ON COLUMN media.sha256 IS
    'SHA-256 of the bytes as received: the original upload (before re-encoding), the fetched Open Library image, or the legacy blob. Uploads whose hash matches a removed row are refused.';
COMMENT ON COLUMN media.variants IS
    'Stored sizes: covers {s,l} (thumbnail and large WebP), avatars {a} (256x256). Legacy avatars are JPEG with variant {a}.';
COMMENT ON COLUMN media.dominant_color IS
    'Spine colour sampled from the image. NULL = not sampled yet, empty string = sampled but no usable colour, else #rrggbb.';
COMMENT ON COLUMN media.fetch_failed_at IS
    'Open Library answered 404/410 for this cover id; not retried for 7 days.';
COMMENT ON COLUMN media.removed_at IS
    'Takedown: bytes deleted from the store, URL answers 410, references are cleared, and the row is never fetched, served or attached again.';

ALTER TABLE users
    ADD CONSTRAINT users_avatar_media_fk FOREIGN KEY (avatar_media_id) REFERENCES media (id) ON DELETE SET NULL;

------------------------------------------------------------------------------
-- Clubs, roles, invites (#40)
------------------------------------------------------------------------------

CREATE TABLE clubs (
    id         bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    slug       text COLLATE "C" NOT NULL
               CONSTRAINT clubs_slug_format CHECK (slug ~ '^[a-z0-9](?:[a-z0-9-]{1,62}[a-z0-9])$'),
    name       text NOT NULL CHECK (char_length(name) BETWEEN 1 AND 80 AND name = btrim(name)),
    timezone   text NOT NULL DEFAULT 'UTC' CHECK (char_length(timezone) BETWEEN 1 AND 64),
    created_by bigint NULL REFERENCES users (id) ON DELETE SET NULL,
    created_at timestamptz NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX clubs_slug_key ON clubs (slug);
CREATE INDEX clubs_created_by_idx ON clubs (created_by) WHERE created_by IS NOT NULL;

COMMENT ON COLUMN clubs.slug IS
    'URL key for /c/{slug} and /api/clubs/{slug}. Immutable. Generated as slugified name + "-" + 4 random characters, so it cannot be probed.';
COMMENT ON COLUMN clubs.timezone IS
    'IANA zone for club times: meeting_at, vote deadlines, milestone due dates and their labels. Defaults to the creator''s zone.';
COMMENT ON COLUMN clubs.created_by IS
    'Counts toward the 10-clubs-created-per-user limit (existing clubs only). Not the owner; ownership lives in club_memberships.';

CREATE TABLE club_memberships (
    club_id    bigint NOT NULL REFERENCES clubs (id) ON DELETE CASCADE,
    user_id    bigint NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    role       text NOT NULL CHECK (role IN ('owner', 'admin', 'member')),
    joined_at  timestamptz NOT NULL DEFAULT now(),
    invited_by bigint NULL REFERENCES users (id) ON DELETE SET NULL,
    PRIMARY KEY (club_id, user_id)
);
CREATE INDEX club_memberships_user_id_idx ON club_memberships (user_id, club_id);
CREATE UNIQUE INDEX club_memberships_one_owner ON club_memberships (club_id) WHERE role = 'owner';

COMMENT ON TABLE club_memberships IS
    'At most 20 rows per club (enforced by the app under a lock on the clubs row). Exactly one owner: at most one by club_memberships_one_owner; at least one by the deferred constraint triggers clubs_have_owner and club_memberships_keep_owner (a backstop: the app blocks owner exits, and every membership write locks the clubs row and re-reads roles first). A transfer demotes the old owner before it promotes the new one.';
COMMENT ON COLUMN club_memberships.joined_at IS
    'Personal activity of a member appears in the club feed only from this moment on. Imported members: users.created_at.';

-- Backstop for "every club has an owner": checked at COMMIT, so a transfer
-- (demote, then promote) and a club creation (club, then owner row) pass, and
-- deleting a club (which cascades its memberships) passes because the club is gone.
CREATE FUNCTION bc_check_club_owner() RETURNS trigger
    LANGUAGE plpgsql AS $$
DECLARE
    cid bigint;
BEGIN
    IF TG_TABLE_NAME = 'clubs' THEN
        cid := NEW.id;
    ELSE
        cid := OLD.club_id;
    END IF;
    IF EXISTS (SELECT 1 FROM clubs WHERE id = cid)
       AND NOT EXISTS (SELECT 1 FROM club_memberships WHERE club_id = cid AND role = 'owner') THEN
        RAISE EXCEPTION 'club % has no owner', cid
            USING ERRCODE = 'check_violation', CONSTRAINT = 'clubs_have_owner';
    END IF;
    RETURN NULL;
END;
$$;
CREATE CONSTRAINT TRIGGER clubs_have_owner
    AFTER INSERT ON clubs
    DEFERRABLE INITIALLY DEFERRED
    FOR EACH ROW EXECUTE FUNCTION bc_check_club_owner();
CREATE CONSTRAINT TRIGGER club_memberships_keep_owner
    AFTER DELETE OR UPDATE OF role ON club_memberships
    DEFERRABLE INITIALLY DEFERRED
    FOR EACH ROW EXECUTE FUNCTION bc_check_club_owner();

-- Members removed by an admin. A removal outlives the membership row so that a
-- removed person cannot walk back in with an invite they already know. (A second
-- account could: the removal therefore also revokes the club's active invites
-- the person knows, clubs::members::remove_member.)
CREATE TABLE club_removals (
    club_id    bigint NOT NULL REFERENCES clubs (id) ON DELETE CASCADE,
    user_id    bigint NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    removed_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (club_id, user_id)
);
CREATE INDEX club_removals_user_id_idx ON club_removals (user_id);

COMMENT ON TABLE club_removals IS
    'Invites created before removed_at cannot be redeemed by this user (400 "That invite code is not valid"). An invite created after the removal can; joining deletes the row. Leaving voluntarily records nothing.';

-- Invites: every invite has a use limit or an expiry (or both). Single-use
-- codes have max_uses = 1; shareable links have an expiry and optionally a
-- limit. club_id NULL = a sign-up-only invite minted by an instance admin for
-- the closed beta (no club to join).
CREATE TABLE club_invites (
    id         bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    club_id    bigint NULL REFERENCES clubs (id) ON DELETE CASCADE,
    code       text COLLATE "C" NOT NULL CHECK (code ~ '^[^[:space:]-]{1,128}$' AND code = upper(code)),
    created_by bigint NULL REFERENCES users (id) ON DELETE SET NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    expires_at timestamptz NULL,
    max_uses   integer NULL CHECK (max_uses BETWEEN 1 AND 100),
    use_count  integer NOT NULL DEFAULT 0 CHECK (use_count >= 0),
    revoked_at timestamptz NULL,
    CONSTRAINT club_invites_limited CHECK (expires_at IS NOT NULL OR max_uses IS NOT NULL),
    CONSTRAINT club_invites_within_limit CHECK (max_uses IS NULL OR use_count <= max_uses)
);
CREATE UNIQUE INDEX club_invites_code_key ON club_invites (code);
CREATE INDEX club_invites_club_id_idx ON club_invites (club_id, created_at DESC);

COMMENT ON COLUMN club_invites.code IS
    'Normalised: whitespace and "-" removed, uppercase. New codes are 10 Crockford base32 characters. Legacy codes are imported verbatim.';
COMMENT ON COLUMN club_invites.use_count IS
    'Incremented atomically by the redeeming UPDATE ... SET use_count = use_count + 1 WHERE code = $1 AND revoked_at IS NULL AND (expires_at IS NULL OR expires_at > now()) AND (max_uses IS NULL OR use_count < max_uses) RETURNING ..., in the same transaction as the membership insert. Link invites have max_uses NULL.';

-- Redemption log (InviteOut.used_by, the export). Not unique: a member who left
-- may redeem the same link again.
CREATE TABLE club_invite_uses (
    id        bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    invite_id bigint NOT NULL REFERENCES club_invites (id) ON DELETE CASCADE,
    user_id   bigint NULL REFERENCES users (id) ON DELETE SET NULL,
    used_at   timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX club_invite_uses_invite_id_idx ON club_invite_uses (invite_id, used_at);
CREATE INDEX club_invite_uses_user_id_idx ON club_invite_uses (user_id) WHERE user_id IS NOT NULL;

------------------------------------------------------------------------------
-- Catalog (#41, #42): works, editions, authors. Global, shared by everyone.
------------------------------------------------------------------------------

CREATE TABLE authors (
    id           bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name         text NOT NULL CHECK (char_length(name) BETWEEN 1 AND 300),
    name_key     text NOT NULL CHECK (char_length(name_key) BETWEEN 1 AND 900),
    sort_name    text NULL CHECK (char_length(sort_name) BETWEEN 1 AND 300),
    ol_author_id text COLLATE "C" NULL CHECK (ol_author_id ~ '^OL[0-9]+A$'),
    gnd_id       text COLLATE "C" NULL CHECK (char_length(gnd_id) BETWEEN 1 AND 32),
    created_at   timestamptz NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX authors_ol_author_id_key ON authors (ol_author_id) WHERE ol_author_id IS NOT NULL;
CREATE UNIQUE INDEX authors_gnd_id_key ON authors (gnd_id) WHERE gnd_id IS NOT NULL;
-- Names without an external id are deduplicated by their case-folded form, so
-- every DNB record without a GND $0 reuses the same row instead of adding one.
CREATE UNIQUE INDEX authors_unlinked_name_key ON authors (name_key)
    WHERE ol_author_id IS NULL AND gnd_id IS NULL;

COMMENT ON COLUMN authors.name IS 'Display name in natural order ("Udo Paulitz"); DNB "Surname, Forename" is turned around by the MARC mapping.';
COMMENT ON COLUMN authors.name_key IS 'text::casefold(collapse_ws(name)), computed in Rust by ingest.';
COMMENT ON COLUMN authors.sort_name IS 'Inverted form as delivered by DNB ("Paulitz, Udo"), when known.';
COMMENT ON COLUMN authors.gnd_id IS 'GND identifier from DNB MARC records (CC0).';

CREATE TABLE works (
    id                 bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    title              text NOT NULL CHECK (char_length(title) BETWEEN 1 AND 1000),
    subtitle           text NOT NULL DEFAULT '' CHECK (char_length(subtitle) <= 1000),
    author_names       text NOT NULL DEFAULT '' CHECK (char_length(author_names) <= 2000),
    first_publish_year integer NULL CHECK (first_publish_year BETWEEN -5000 AND 3000),
    description        text NOT NULL DEFAULT '' CHECK (char_length(description) <= 50000),
    subjects           text[] NOT NULL DEFAULT '{}' CHECK (cardinality(subjects) <= 50),
    pages              integer NULL CHECK (pages BETWEEN 1 AND 100000),
    ol_work_id         text COLLATE "C" NULL CHECK (ol_work_id ~ '^OL[0-9]+W$'),
    ol_rating          double precision NULL CHECK (ol_rating BETWEEN 0 AND 5),
    ol_rating_count    integer NULL CHECK (ol_rating_count >= 0),
    source             text NOT NULL CHECK (source IN ('openlibrary', 'dnb', 'user', 'legacy')),
    cover_media_id     bigint NULL REFERENCES media (id) ON DELETE SET NULL,
    created_by         bigint NULL REFERENCES users (id) ON DELETE SET NULL,
    details_fetched_at timestamptz NULL,
    field_sources      jsonb NOT NULL DEFAULT '{}' CHECK (jsonb_typeof(field_sources) = 'object'),
    search_extra       text NOT NULL DEFAULT '' CHECK (char_length(search_extra) <= 5000),
    match_key          text NULL CHECK (char_length(match_key) BETWEEN 1 AND 1500),
    merged_into_id     bigint NULL REFERENCES works (id) ON DELETE RESTRICT,
    created_at         timestamptz NOT NULL DEFAULT now(),
    updated_at         timestamptz NOT NULL DEFAULT now(),
    search_vector      tsvector GENERATED ALWAYS AS (
                           setweight(to_tsvector('simple'::regconfig,
                                     bc_unaccent(title || ' ' || subtitle || ' ' || search_extra)), 'A')
                           || setweight(to_tsvector('simple'::regconfig, bc_unaccent(author_names)), 'B')
                       ) STORED,
    CONSTRAINT works_not_merged_into_self CHECK (merged_into_id IS NULL OR merged_into_id <> id)
);
CREATE UNIQUE INDEX works_ol_work_id_key ON works (ol_work_id) WHERE ol_work_id IS NOT NULL;
CREATE INDEX works_search_vector_idx ON works USING gin (search_vector);
CREATE INDEX works_search_trgm_idx ON works USING gin (bc_search_text(title, author_names, search_extra) gin_trgm_ops);
CREATE INDEX works_cover_media_id_idx ON works (cover_media_id) WHERE cover_media_id IS NOT NULL;
CREATE INDEX works_dnb_match_key_idx ON works (match_key) WHERE source = 'dnb' AND merged_into_id IS NULL;

COMMENT ON COLUMN works.author_names IS
    'Display string ("A, B", natural name order), authoritative for display and search. work_authors links author records when the source provides them; legacy bare-facts works may have none.';
COMMENT ON COLUMN works.first_publish_year IS
    'Open Library first_publish_year. Works built from edition facts (DNB, legacy bare facts) take the edition''s publication_year; ingest also fills a NULL value from the first edition that has one.';
COMMENT ON COLUMN works.pages IS
    'Typical page count (Open Library number_of_pages_median). Used when a shelf entry has no edition; an edition''s own pages win. ingest fills a NULL value from the first edition that has pages.';
COMMENT ON COLUMN works.cover_media_id IS
    'Work-level cover, used whenever BookOut has no edition context. ingest fills a NULL value from an edition cover, so a DNB work or a work whose only cover is a user photo of an edition still shows one.';
COMMENT ON COLUMN works.source IS
    'Origin of the row. openlibrary: has ol_work_id; dnb: created by the DNB harvester or SRU lookup; user: added by a reader (legacy BC... books too); legacy: bare facts from an unmatched legacy Google/other row. A legacy work becomes dnb or openlibrary the first time a record of that source is ingested into it (its legacy-ranked fields are overwritten in the same statement); user works keep source user. Per-field origin is field_sources.';
COMMENT ON COLUMN works.details_fetched_at IS
    'openlibrary: NULL = stub (only search-hit facts); the first detail view fetches the full record once, refresh fetches again. dnb: NULL = the one-time Open Library cover check by ISBN has not run yet.';
COMMENT ON COLUMN works.field_sources IS
    'Per-field provenance, maintained by ingest: {"<column>": "admin"|"user"|"dnb"|"openlibrary"|"legacy"} for title, subtitle, author_names (with work_authors), first_publish_year, description, subjects, pages and cover_media_id when they hold a value. Rank admin > user > dnb = openlibrary > legacy. A source may fill an empty field and overwrite a field of equal or lower rank, never a user or admin field. Approving an edit request sets "admin".';
COMMENT ON COLUMN works.search_extra IS
    'Edition titles that differ from the work title (deduplicated by case fold, " / "-joined), maintained by ingest so a translated or retitled edition is found by its own title.';
COMMENT ON COLUMN works.match_key IS
    'text::casefold of the title plus U+001F plus the case-folded surname of the first author; computed in Rust by ingest. Used by the DNB grouping step (WorkGrouping::DnbTitleAuthor).';
COMMENT ON COLUMN works.merged_into_id IS
    'Set when an admin merged this work into another (catalog::merge_works). All references were re-pointed; the row stays only to redirect old links and is excluded from search.';

CREATE TABLE work_authors (
    work_id   bigint NOT NULL REFERENCES works (id) ON DELETE CASCADE,
    author_id bigint NOT NULL REFERENCES authors (id) ON DELETE RESTRICT,
    position  integer NOT NULL CHECK (position >= 0),
    PRIMARY KEY (work_id, author_id)
);
CREATE INDEX work_authors_author_id_idx ON work_authors (author_id);

CREATE TABLE editions (
    id                       bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    work_id                  bigint NOT NULL REFERENCES works (id) ON DELETE CASCADE,
    isbn13                   text COLLATE "C" NULL CHECK (isbn13 ~ '^97[89][0-9]{10}$'),
    title                    text NULL CHECK (char_length(title) BETWEEN 1 AND 1000),
    subtitle                 text NULL CHECK (char_length(subtitle) <= 1000),
    publisher                text NOT NULL DEFAULT '' CHECK (char_length(publisher) <= 300),
    language                 text NULL CHECK (language ~ '^[a-z]{3}$'),
    format                   text NULL CHECK (format IN ('hardcover', 'paperback', 'ebook', 'audiobook', 'other')),
    pages                    integer NULL CHECK (pages BETWEEN 1 AND 100000),
    publication_year         integer NULL CHECK (publication_year BETWEEN -5000 AND 3000),
    planned_publication_date date NULL,
    ol_edition_id            text COLLATE "C" NULL CHECK (ol_edition_id ~ '^OL[0-9]+M$'),
    dnb_idn                  text COLLATE "C" NULL CHECK (char_length(dnb_idn) BETWEEN 1 AND 32),
    source                   text NOT NULL CHECK (source IN ('openlibrary', 'dnb', 'user', 'legacy')),
    cover_media_id           bigint NULL REFERENCES media (id) ON DELETE SET NULL,
    created_by               bigint NULL REFERENCES users (id) ON DELETE SET NULL,
    field_sources            jsonb NOT NULL DEFAULT '{}' CHECK (jsonb_typeof(field_sources) = 'object'),
    withdrawn_at             timestamptz NULL,
    created_at               timestamptz NOT NULL DEFAULT now(),
    updated_at               timestamptz NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX editions_isbn13_key ON editions (isbn13) WHERE isbn13 IS NOT NULL;
CREATE UNIQUE INDEX editions_ol_edition_id_key ON editions (ol_edition_id) WHERE ol_edition_id IS NOT NULL;
CREATE UNIQUE INDEX editions_dnb_idn_key ON editions (dnb_idn) WHERE dnb_idn IS NOT NULL;
CREATE INDEX editions_work_id_idx ON editions (work_id);
CREATE INDEX editions_planned_idx ON editions (planned_publication_date)
    WHERE planned_publication_date IS NOT NULL AND withdrawn_at IS NULL;

COMMENT ON COLUMN editions.isbn13 IS
    'Canonical ISBN. ISBN-10 input is converted to 978-ISBN-13 before every lookup; 979 ISBNs have no ISBN-10. Checksums are validated. There is no isbn10 column: EditionOut.isbn10 is derived (isbn::isbn10_of), so the two can never disagree.';
COMMENT ON COLUMN editions.title IS 'Only when it differs from the work title (e.g. a translation). Also feeds works.search_extra.';
COMMENT ON COLUMN editions.language IS 'ISO 639-2/B code (MARC 008/35-37 or 041), e.g. ger, eng.';
COMMENT ON COLUMN editions.format IS
    'DNB: 653 (Produktform), else the 020 $c binding, else 337/338 (catalog::shared::dnb_marc). Open Library: physical_format.';
COMMENT ON COLUMN editions.planned_publication_date IS
    'MARC 263 as last delivered by DNB; first day of the month when only the month is known. Only a record that carries 263 changes it, so it keeps the announced date after publication. new-releases filters by a date window, never by "NULL once published".';
COMMENT ON COLUMN editions.dnb_idn IS 'DNB record identifier (IDN, MARC 001) of the newest record that matched this edition. Upsert key for the harvester (after isbn13).';
COMMENT ON COLUMN editions.field_sources IS
    'Per-field provenance, as works.field_sources, for title, subtitle, publisher, language, format, pages, publication_year, planned_publication_date, cover_media_id and contributors.';
COMMENT ON COLUMN editions.withdrawn_at IS
    'DNB delivered an OAI header with status="deleted" for this record (a withdrawn announcement). The row stays (shelves may point at it) and still resolves by ISBN; new-releases skips it. A later live record for the same IDN or ISBN clears it.';

CREATE TABLE edition_contributors (
    edition_id bigint NOT NULL REFERENCES editions (id) ON DELETE CASCADE,
    author_id  bigint NOT NULL REFERENCES authors (id) ON DELETE RESTRICT,
    role       text NOT NULL CHECK (role IN ('translator', 'illustrator', 'editor')),
    position   integer NOT NULL CHECK (position >= 0),
    PRIMARY KEY (edition_id, author_id, role)
);

-- Permanent map from legacy book keys to works, for the importer report and for
-- old links (/book/OL...W, /book/BC..., /book/ISBN..., /book/GB...).
CREATE TABLE legacy_work_keys (
    legacy_key     text COLLATE "C" PRIMARY KEY CHECK (legacy_key ~ '^(/works/.+|sha256:[0-9a-f]{64})$'),
    legacy_book_id bigint NOT NULL,
    work_id        bigint NOT NULL REFERENCES works (id) ON DELETE RESTRICT,
    edition_id     bigint NULL REFERENCES editions (id) ON DELETE SET NULL,
    match          text NOT NULL CHECK (match IN (
                       'openlibrary', 'user', 'isbn_matched', 'isbn_unmatched', 'isbn_error',
                       'isbn_invalid', 'google_volume', 'other'))
);
CREATE UNIQUE INDEX legacy_work_keys_book_id_key ON legacy_work_keys (legacy_book_id);
CREATE INDEX legacy_work_keys_work_id_idx ON legacy_work_keys (work_id);

COMMENT ON COLUMN legacy_work_keys.legacy_key IS
    'books.ol_work_key from the legacy SQLite DB, canonicalised like the legacy app (ISBN x -> X). Google volume ids are not stored: a GB key is kept as "sha256:" + hex(SHA-256 of the canonical "/works/GB..." key, case-sensitive), and WorkRef hashes an incoming GB key the same way.';
COMMENT ON COLUMN legacy_work_keys.edition_id IS
    'The edition the legacy ISBN key resolved to, if any. The importer also sets it as edition_id on the shelf entries and quotes of that book: the legacy row identified exactly this edition by its ISBN.';

-- Admin queue (#41 edits, #43 cover replacements). Phase 2 #54 builds the UI.
CREATE TABLE catalog_edit_requests (
    id            bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    kind          text NOT NULL CHECK (kind IN ('work_edit', 'edition_edit', 'cover_replace', 'work_merge')),
    work_id       bigint NULL REFERENCES works (id) ON DELETE CASCADE,
    edition_id    bigint NULL REFERENCES editions (id) ON DELETE CASCADE,
    media_id      bigint NULL REFERENCES media (id) ON DELETE CASCADE,
    payload       jsonb NOT NULL DEFAULT '{}' CHECK (jsonb_typeof(payload) = 'object'),
    note          text NOT NULL DEFAULT '' CHECK (char_length(note) <= 2000),
    status        text NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'approved', 'rejected')),
    created_by    bigint NULL REFERENCES users (id) ON DELETE SET NULL,
    created_at    timestamptz NOT NULL DEFAULT now(),
    decided_by    bigint NULL REFERENCES users (id) ON DELETE SET NULL,
    decided_at    timestamptz NULL,
    decision_note text NOT NULL DEFAULT '' CHECK (char_length(decision_note) <= 2000),
    CONSTRAINT catalog_edit_requests_target CHECK (work_id IS NOT NULL OR edition_id IS NOT NULL),
    CONSTRAINT catalog_edit_requests_cover CHECK ((kind = 'cover_replace') = (media_id IS NOT NULL))
);
CREATE INDEX catalog_edit_requests_open_idx ON catalog_edit_requests (created_at) WHERE status = 'open';

COMMENT ON COLUMN catalog_edit_requests.payload IS
    'work_edit/edition_edit: {"field": proposed value, ...}; work_merge: {"into_work_id": n} (work_id = the work merged away); cover_replace: {}. Approval applies fields through ingest with provenance "admin"; a merge runs catalog::merge_works.';

-- Notice-and-takedown: any signed-in user can report any cover.
CREATE TABLE reports (
    id          bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    target_kind text NOT NULL CHECK (target_kind IN ('cover')),
    media_id    bigint NULL REFERENCES media (id) ON DELETE SET NULL,
    work_id     bigint NULL REFERENCES works (id) ON DELETE SET NULL,
    edition_id  bigint NULL REFERENCES editions (id) ON DELETE SET NULL,
    reason      text NOT NULL CHECK (reason IN ('copyright', 'wrong_book', 'offensive', 'other')),
    details     text NOT NULL DEFAULT '' CHECK (char_length(details) <= 2000),
    status      text NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'removed', 'dismissed')),
    created_by  bigint NULL REFERENCES users (id) ON DELETE SET NULL,
    created_at  timestamptz NOT NULL DEFAULT now(),
    resolved_by bigint NULL REFERENCES users (id) ON DELETE SET NULL,
    resolved_at timestamptz NULL
);
CREATE INDEX reports_open_idx ON reports (created_at) WHERE status = 'open';
CREATE INDEX reports_media_id_idx ON reports (media_id) WHERE media_id IS NOT NULL;

-- DNB OAI-PMH harvester cursor (#42). One row per harvested set.
CREATE TABLE harvest_state (
    source           text COLLATE "C" PRIMARY KEY CHECK (source ~ '^[a-zA-Z0-9:._-]+$'),
    harvested_until  timestamptz NULL,
    resumption_token text NULL,
    token_issued_at  timestamptz NULL,
    run_started_at   timestamptz NULL,
    run_from         timestamptz NULL,
    last_success_at  timestamptz NULL,
    last_error       text NULL,
    last_error_at    timestamptz NULL,
    records_seen     bigint NOT NULL DEFAULT 0,
    CONSTRAINT harvest_state_token_time CHECK ((resumption_token IS NULL) = (token_issued_at IS NULL))
);

COMMENT ON COLUMN harvest_state.source IS 'e.g. "dnb:dnb-all:reiheN", "dnb:dnb:reiheA" ("dnb:" + the OAI setSpec).';
COMMENT ON COLUMN harvest_state.harvested_until IS
    'OAI "from" for the next run: the start time of the last completed run minus 1 h. NULL before the first run, which starts at now - DNB_HARVEST_START_DAYS.';
COMMENT ON COLUMN harvest_state.resumption_token IS
    'Written in the same transaction as the upserts of the page it continues from (with records_seen), so a crash resumes after the last committed page. NULL between runs. Cleared, and the run restarted from run_from, when DNB answers badResumptionToken or the token is older than 6 h.';
COMMENT ON COLUMN harvest_state.run_from IS 'The OAI "from" of the current run; a restarted run uses it again.';

------------------------------------------------------------------------------
-- Personal data (#44): owned by a user, no club_id. Read access for other
-- users always goes through the policy functions at the end of this file (#46):
-- bc_visible_shelf, bc_visible_quotes, bc_visible_posts, bc_visible_owners for
-- lists, bc_can_see_user / bc_can_see_item / bc_can_see_post for single checks.
------------------------------------------------------------------------------

CREATE TABLE shelf_entries (
    id                bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id           bigint NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    work_id           bigint NOT NULL REFERENCES works (id) ON DELETE RESTRICT,
    edition_id        bigint NULL REFERENCES editions (id) ON DELETE SET NULL,
    status            text COLLATE "C" NOT NULL
                      CHECK (status IN ('want_to_read', 'currently_reading', 'finished', 'did_not_finish')),
    position          integer NOT NULL DEFAULT 0 CHECK (position >= 0),
    shelf_position    integer NULL CHECK (shelf_position >= 0),
    rating            integer NULL CHECK (rating BETWEEN 1 AND 5),
    rating_visibility text NOT NULL DEFAULT 'audience' CHECK (rating_visibility IN ('audience', 'only_me')),
    take              text NOT NULL DEFAULT '' CHECK (char_length(take) <= 140),
    dnf_reason        text NOT NULL DEFAULT '' CHECK (char_length(dnf_reason) <= 200),
    progress          integer NULL CHECK (progress BETWEEN 0 AND 100),
    updated_at        timestamptz NOT NULL DEFAULT now(),
    started_at        timestamptz NULL,
    finished_at       timestamptz NULL,
    CONSTRAINT shelf_entries_user_work_key UNIQUE (user_id, work_id),
    CONSTRAINT shelf_entries_rating_finished CHECK (rating IS NULL OR status = 'finished'),
    CONSTRAINT shelf_entries_take_finished CHECK (take = '' OR status = 'finished'),
    CONSTRAINT shelf_entries_dnf_reason CHECK (dnf_reason = '' OR status = 'did_not_finish'),
    CONSTRAINT shelf_entries_progress_reading CHECK (progress IS NULL OR status = 'currently_reading')
);
CREATE INDEX shelf_entries_user_status_idx ON shelf_entries (user_id, status, position, id);
CREATE INDEX shelf_entries_work_id_idx ON shelf_entries (work_id);

COMMENT ON COLUMN shelf_entries.edition_id IS 'The edition the user owns or reads, optional. Its pages and cover win over the work''s.';
COMMENT ON COLUMN shelf_entries.position IS '0-based order inside the (user, status) column; renumbered densely on every move.';
COMMENT ON COLUMN shelf_entries.shelf_position IS
    'Optional manual order across all statuses. NULL = not arranged yet (sorts first). Not compacted on delete.';
COMMENT ON COLUMN shelf_entries.rating_visibility IS
    'only_me hides rating and take from everyone else (shelf, book readers, club readers, stats, activity payloads).';
COMMENT ON COLUMN shelf_entries.finished_at IS
    'Set by status transitions; finished_on edits store 12:00 in the user''s timezone. May be NULL for a finished entry whose date was cleared.';

CREATE TABLE physical_shelf_layouts (
    user_id    bigint PRIMARY KEY REFERENCES users (id) ON DELETE CASCADE,
    layout     jsonb NOT NULL CHECK (jsonb_typeof(layout) = 'object'),
    updated_at timestamptz NOT NULL DEFAULT now()
);

COMMENT ON COLUMN physical_shelf_layouts.layout IS
    '{"rows": [[<shelf entry id> | "decor:<id>", ...], ...], "material", "lights", "spines": {"<shelf entry id>": {...}}, "decorations": {...}}. Ids are shelf_entries.id (kept by the importer); pruned on entry delete and on read.';

CREATE TABLE user_favorites (
    user_id  bigint NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    work_id  bigint NOT NULL REFERENCES works (id) ON DELETE RESTRICT,
    position integer NOT NULL CHECK (position BETWEEN 1 AND 3),
    PRIMARY KEY (user_id, work_id),
    CONSTRAINT user_favorites_position_key UNIQUE (user_id, position) DEFERRABLE INITIALLY IMMEDIATE
);
CREATE INDEX user_favorites_work_id_idx ON user_favorites (work_id);

COMMENT ON CONSTRAINT user_favorites_position_key ON user_favorites IS
    'Deferrable so positions can be compacted with one UPDATE inside a transaction.';

CREATE TABLE search_history (
    id               bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id          bigint NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    query            text NOT NULL CHECK (char_length(query) BETWEEN 1 AND 300),
    normalized_query text NOT NULL CHECK (char_length(normalized_query) BETWEEN 1 AND 900),
    last_used_at     timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT search_history_user_query_key UNIQUE (user_id, normalized_query)
);
CREATE INDEX search_history_user_recent_idx ON search_history (user_id, last_used_at DESC, id DESC);

COMMENT ON COLUMN search_history.normalized_query IS
    'Unicode full case fold of query (computed in Rust: "Straße" -> "strasse"). Postgres lower() is not a case fold, so never compute it in SQL.';

CREATE TABLE quotes (
    id         bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id    bigint NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    work_id    bigint NOT NULL REFERENCES works (id) ON DELETE RESTRICT,
    edition_id bigint NULL REFERENCES editions (id) ON DELETE SET NULL,
    body       text NOT NULL CHECK (char_length(body) BETWEEN 1 AND 1000),
    page       integer NULL CHECK (page BETWEEN 0 AND 20000),
    visibility text NOT NULL DEFAULT 'audience' CHECK (visibility IN ('audience', 'only_me')),
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NULL
);
CREATE INDEX quotes_user_id_idx ON quotes (user_id, id DESC);
CREATE INDEX quotes_work_id_idx ON quotes (work_id, id DESC);

COMMENT ON COLUMN quotes.edition_id IS
    'The edition `page` refers to. Defaults to the user''s shelf edition for the work at creation time; NULL = unknown edition.';

------------------------------------------------------------------------------
-- Club data (#45): every table carries club_id; children reference their
-- parent through (club_id, parent_id).
------------------------------------------------------------------------------

CREATE TABLE club_picks (
    id               bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    club_id          bigint NOT NULL REFERENCES clubs (id) ON DELETE CASCADE,
    work_id          bigint NOT NULL REFERENCES works (id) ON DELETE RESTRICT,
    set_by           bigint NULL REFERENCES users (id) ON DELETE SET NULL,
    note             text NOT NULL DEFAULT '' CHECK (char_length(note) <= 280),
    started_at       timestamptz NOT NULL DEFAULT now(),
    ended_at         timestamptz NULL,
    meeting_at       timestamptz NULL,
    reminder_sent_at timestamptz NULL,
    CONSTRAINT club_picks_club_id_id_key UNIQUE (club_id, id)
);
CREATE UNIQUE INDEX club_picks_one_current ON club_picks (club_id) WHERE ended_at IS NULL;
CREATE INDEX club_picks_history_idx ON club_picks (club_id, ended_at DESC, id DESC) WHERE ended_at IS NOT NULL;
CREATE INDEX club_picks_work_id_idx ON club_picks (work_id);

COMMENT ON COLUMN club_picks.ended_at IS 'NULL = the current pick; at most one per club (partial unique index).';
COMMENT ON COLUMN club_picks.meeting_at IS 'The one optional meeting for this pick, UTC; entered in the club timezone.';
COMMENT ON COLUMN club_picks.reminder_sent_at IS
    'Phase 4: the 24 h push reminder was sent. Imported and kept so Phase 4 never re-sends; unused in Phase 1.';

CREATE TABLE milestones (
    id         bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    club_id    bigint NOT NULL,
    pick_id    bigint NOT NULL,
    title      text NOT NULL CHECK (char_length(title) BETWEEN 1 AND 120),
    unit       text NULL CHECK (unit IN ('percent', 'chapter')),
    range_from integer NULL CHECK (range_from >= 0),
    range_to   integer NULL CHECK (range_to >= 0),
    due_at     timestamptz NULL,
    position   integer NOT NULL DEFAULT 0 CHECK (position >= 0),
    created_by bigint NULL REFERENCES users (id) ON DELETE SET NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT milestones_pick_fk FOREIGN KEY (club_id, pick_id)
        REFERENCES club_picks (club_id, id) ON DELETE CASCADE,
    CONSTRAINT milestones_pick_id_id_key UNIQUE (pick_id, id),
    CONSTRAINT milestones_unit_needs_range CHECK (unit IS NOT NULL OR (range_from IS NULL AND range_to IS NULL)),
    CONSTRAINT milestones_percent_range CHECK (unit IS DISTINCT FROM 'percent'
        OR (coalesce(range_from, 0) <= 100 AND coalesce(range_to, 0) <= 100)),
    CONSTRAINT milestones_range_order CHECK (range_from IS NULL OR range_to IS NULL OR range_from <= range_to)
);
CREATE INDEX milestones_pick_idx ON milestones (pick_id, position, id);

COMMENT ON COLUMN milestones.unit IS
    'percent or chapter; NULL = a title-only checkpoint (legacy milestones without chapters).';
COMMENT ON COLUMN milestones.range_from IS
    'Inclusive start of the range, or NULL for an open start ("up to range_to"). Legacy chapter_from.';

-- Posts: one table for personal diary entries (club_id NULL) and club pick
-- discussion posts (club_id + pick_id set). Same shape, replies, reactions and
-- tombstones; different read rule (audience + visibility vs club membership).
CREATE TABLE posts (
    id           bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    work_id      bigint NOT NULL REFERENCES works (id) ON DELETE RESTRICT,
    author_id    bigint NULL REFERENCES users (id) ON DELETE SET NULL,
    parent_id    bigint NULL,
    club_id      bigint NULL REFERENCES clubs (id) ON DELETE CASCADE,
    scope_key    bigint GENERATED ALWAYS AS (coalesce(club_id, 0)) STORED NOT NULL,
    pick_id      bigint NULL,
    milestone_id bigint NULL,
    visibility   text NOT NULL DEFAULT 'audience' CHECK (visibility IN ('audience', 'only_me')),
    body         text NOT NULL CHECK (char_length(body) <= 1000),
    spoiler_upto integer NULL CHECK (spoiler_upto BETWEEN 0 AND 100),
    progress_at  integer NULL CHECK (progress_at BETWEEN 0 AND 100),
    status_at    text NULL CHECK (status_at IN ('want_to_read', 'currently_reading', 'finished', 'did_not_finish')),
    deleted_at   timestamptz NULL,
    created_at   timestamptz NOT NULL DEFAULT now(),
    updated_at   timestamptz NULL,
    -- A reply is on its parent's work and in its parent's scope (the same club,
    -- or both personal). Structural, so a club delete can never be blocked by a
    -- cross-scope reply. ON DELETE NO ACTION: a parent with replies is tombstoned,
    -- never deleted; a whole thread goes in one statement (club delete, merge).
    CONSTRAINT posts_thread_key UNIQUE (id, work_id, scope_key),
    CONSTRAINT posts_parent_fk FOREIGN KEY (parent_id, work_id, scope_key)
        REFERENCES posts (id, work_id, scope_key) ON DELETE NO ACTION ON UPDATE NO ACTION,
    CONSTRAINT posts_pick_fk FOREIGN KEY (club_id, pick_id)
        REFERENCES club_picks (club_id, id) ON DELETE CASCADE,
    CONSTRAINT posts_milestone_fk FOREIGN KEY (pick_id, milestone_id)
        REFERENCES milestones (pick_id, id) ON DELETE SET NULL (milestone_id),
    CONSTRAINT posts_club_needs_pick CHECK ((club_id IS NULL) = (pick_id IS NULL)),
    CONSTRAINT posts_milestone_club_only CHECK (milestone_id IS NULL OR club_id IS NOT NULL),
    CONSTRAINT posts_visibility_scope CHECK (visibility = 'audience' OR (club_id IS NULL AND parent_id IS NULL)),
    CONSTRAINT posts_live_has_body CHECK (deleted_at IS NOT NULL OR char_length(body) >= 1),
    CONSTRAINT posts_live_has_author CHECK (deleted_at IS NOT NULL OR author_id IS NOT NULL),
    CONSTRAINT posts_tombstone_cleared CHECK (deleted_at IS NULL OR (body = '' AND spoiler_upto IS NULL)),
    CONSTRAINT posts_not_own_parent CHECK (parent_id IS NULL OR parent_id <> id)
);
CREATE INDEX posts_work_thread_idx ON posts (work_id, created_at, id) WHERE parent_id IS NULL;
CREATE INDEX posts_parent_id_idx ON posts (parent_id, created_at, id) WHERE parent_id IS NOT NULL;
CREATE INDEX posts_author_id_idx ON posts (author_id, id DESC) WHERE author_id IS NOT NULL;
CREATE INDEX posts_pick_thread_idx ON posts (club_id, pick_id, created_at, id) WHERE club_id IS NOT NULL;
CREATE INDEX posts_milestone_idx ON posts (milestone_id) WHERE milestone_id IS NOT NULL;

COMMENT ON TABLE posts IS
    'club_id NULL: personal diary entry, visible to the author''s audience unless only_me. club_id set: pick discussion post, visible to club members only. Replies are on the same work and in the same scope as their parent (posts_parent_fk) and one level deep (the parent has parent_id NULL; checked by the app and the importer). A post with replies is never hard-deleted: it becomes a tombstone. Read access: bc_visible_posts / bc_can_see_post.';
COMMENT ON COLUMN posts.author_id IS
    'NULL only on tombstones left behind by a deleted account (live posts always have an author, see posts_live_has_author). Such a diary tombstone is visible to whoever can see one of its replies, unless it is only_me (bc_visible_posts).';
COMMENT ON COLUMN posts.scope_key IS 'coalesce(club_id, 0): the thread scope used by posts_parent_fk.';
COMMENT ON COLUMN posts.visibility IS 'Diary roots only; replies and club posts are always audience.';
COMMENT ON COLUMN posts.spoiler_upto IS 'Percent of the book the post is safe up to; NULL = no spoiler flag.';
COMMENT ON COLUMN posts.progress_at IS 'Snapshot of the author''s progress when writing (100 when finished).';
COMMENT ON COLUMN posts.deleted_at IS 'Tombstone marker: body cleared, kept so replies keep their anchor.';

CREATE TABLE post_reactions (
    post_id    bigint NOT NULL REFERENCES posts (id) ON DELETE CASCADE,
    user_id    bigint NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    emoji      text NOT NULL CHECK (emoji IN (
                   U&'\2764\FE0F', U&'\+01F44D', U&'\+01F602', U&'\+01F62E', U&'\+01F525', U&'\+01F4DA')),
    created_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (post_id, user_id, emoji)
);
CREATE INDEX post_reactions_user_id_idx ON post_reactions (user_id);

COMMENT ON COLUMN post_reactions.emoji IS
    'Exact strings, compared by code point: red heart + VS16, thumbs up, tears of joy, open mouth, fire, books.';

CREATE TABLE next_up_votes (
    id                   bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    club_id              bigint NOT NULL REFERENCES clubs (id) ON DELETE CASCADE,
    started_at           timestamptz NOT NULL DEFAULT now(),
    ended_at             timestamptz NULL,
    closes_at            timestamptz NULL,
    winner_nomination_id bigint NULL,   -- FK added below
    CONSTRAINT next_up_votes_club_id_id_key UNIQUE (club_id, id)
);
CREATE UNIQUE INDEX next_up_votes_one_open ON next_up_votes (club_id) WHERE ended_at IS NULL;

COMMENT ON COLUMN next_up_votes.closes_at IS
    'Optional deadline. Checked lazily (GET vote, nominate, cast): the leader is applied, or with no ballots the deadline is cleared.';

CREATE TABLE next_up_nominations (
    id           bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    club_id      bigint NOT NULL,
    vote_id      bigint NOT NULL,
    work_id      bigint NOT NULL REFERENCES works (id) ON DELETE RESTRICT,
    nominated_by bigint NULL REFERENCES users (id) ON DELETE SET NULL,
    created_at   timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT next_up_nominations_vote_fk FOREIGN KEY (club_id, vote_id)
        REFERENCES next_up_votes (club_id, id) ON DELETE CASCADE,
    CONSTRAINT next_up_nominations_vote_work_key UNIQUE (vote_id, work_id),
    CONSTRAINT next_up_nominations_vote_id_id_key UNIQUE (vote_id, id)
);
CREATE INDEX next_up_nominations_work_id_idx ON next_up_nominations (work_id);

ALTER TABLE next_up_votes
    ADD CONSTRAINT next_up_votes_winner_fk FOREIGN KEY (id, winner_nomination_id)
        REFERENCES next_up_nominations (vote_id, id) ON DELETE SET NULL (winner_nomination_id);

CREATE TABLE next_up_ballots (
    club_id       bigint NOT NULL,
    vote_id       bigint NOT NULL,
    user_id       bigint NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    nomination_id bigint NOT NULL,
    created_at    timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (vote_id, user_id),
    CONSTRAINT next_up_ballots_vote_fk FOREIGN KEY (club_id, vote_id)
        REFERENCES next_up_votes (club_id, id) ON DELETE CASCADE,
    CONSTRAINT next_up_ballots_nomination_fk FOREIGN KEY (vote_id, nomination_id)
        REFERENCES next_up_nominations (vote_id, id) ON DELETE CASCADE
);
CREATE INDEX next_up_ballots_nomination_idx ON next_up_ballots (nomination_id);

COMMENT ON COLUMN next_up_ballots.created_at IS 'First cast; unchanged when the ballot moves to another nomination.';

-- Append-only activity log. Club events carry club_id; personal events
-- (shelf_*, progress, quote_added) have club_id NULL and are joined into club
-- feeds at read time for current members (from their joined_at), filtered by
-- the visibility policy and redacted for only_me items.
CREATE TABLE events (
    id         bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    club_id    bigint NULL REFERENCES clubs (id) ON DELETE CASCADE,
    actor_id   bigint NULL REFERENCES users (id) ON DELETE CASCADE,
    kind       text NOT NULL CHECK (kind IN (
                   'member_joined', 'pick_set', 'pick_cleared', 'note_posted', 'reaction',
                   'nominated', 'voted', 'vote_closed', 'milestone_added',
                   'shelf_added', 'shelf_moved', 'shelf_finished', 'shelf_dnf', 'shelf_removed',
                   'progress', 'quote_added')),
    work_id    bigint NULL REFERENCES works (id) ON DELETE RESTRICT,
    pick_id    bigint NULL,
    payload    jsonb NOT NULL DEFAULT '{}' CHECK (jsonb_typeof(payload) = 'object'),
    created_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT events_pick_fk FOREIGN KEY (club_id, pick_id)
        REFERENCES club_picks (club_id, id) ON DELETE CASCADE,
    CONSTRAINT events_scope CHECK ((club_id IS NULL) = (kind IN (
        'shelf_added', 'shelf_moved', 'shelf_finished', 'shelf_dnf', 'shelf_removed', 'progress', 'quote_added'))),
    CONSTRAINT events_personal_has_actor CHECK (club_id IS NOT NULL OR actor_id IS NOT NULL),
    -- events_pick_fk is MATCH SIMPLE and skipped when club_id is NULL, so this
    -- keeps a personal event from carrying (and leaking) a club's pick id.
    CONSTRAINT events_personal_no_pick CHECK (club_id IS NOT NULL OR pick_id IS NULL)
);
CREATE INDEX events_club_feed_idx ON events (club_id, id DESC) WHERE club_id IS NOT NULL;
CREATE INDEX events_personal_feed_idx ON events (actor_id, id DESC) WHERE club_id IS NULL;
CREATE INDEX events_work_id_idx ON events (work_id) WHERE work_id IS NOT NULL;

COMMENT ON COLUMN events.actor_id IS
    'NULL only for system club events (an auto-closed vote whose nominator account was deleted). Events of a deleted account are deleted with it.';
COMMENT ON COLUMN events.payload IS
    'Kind-specific JSON object with null values dropped. References instead of names, resolved at read time: quote_added {"quote_id","page"?,"excerpt"}, note_posted {"post_id"}, reaction {"emoji","post_id","author_id"?} (posts.id, users.id; the feed turns author_id into the legacy "author" username, null once the account is gone). No payload ever stores a username: usernames are freed when an account is deleted.';

------------------------------------------------------------------------------
-- Background jobs
------------------------------------------------------------------------------

-- Goodreads CSV imports run as a background job (400 rows at <= 3 Open Library
-- requests per second can take minutes). Parsed rows are kept so a restarted
-- server resumes at `processed`.
CREATE TABLE import_jobs (
    id          bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id     bigint NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    kind        text NOT NULL DEFAULT 'goodreads' CHECK (kind IN ('goodreads')),
    status      text NOT NULL DEFAULT 'queued' CHECK (status IN ('queued', 'running', 'done', 'failed')),
    rows        jsonb NOT NULL DEFAULT '[]' CHECK (jsonb_typeof(rows) = 'array'),
    total       integer NOT NULL DEFAULT 0 CHECK (total >= 0),
    processed   integer NOT NULL DEFAULT 0 CHECK (processed >= 0),
    imported    integer NOT NULL DEFAULT 0 CHECK (imported >= 0),
    skipped     integer NOT NULL DEFAULT 0 CHECK (skipped >= 0),
    skips       jsonb NOT NULL DEFAULT '[]' CHECK (jsonb_typeof(skips) = 'array'),
    error       text NULL,
    created_at  timestamptz NOT NULL DEFAULT now(),
    finished_at timestamptz NULL
);
CREATE UNIQUE INDEX import_jobs_one_active ON import_jobs (user_id) WHERE status IN ('queued', 'running');
CREATE INDEX import_jobs_user_id_idx ON import_jobs (user_id, id DESC);

COMMENT ON COLUMN import_jobs.rows IS
    'Parsed CSV rows still to process ({title, authors, isbn13?, status, rating?, read_on?}); emptied when the job finishes.';
COMMENT ON COLUMN import_jobs.skips IS 'First 25 skips: [{"title", "code", "reason"}]; `skipped` counts all of them.';

------------------------------------------------------------------------------
-- Visibility policy (#46). The ONE definition of "who may see whose personal
-- data" and "which club rows a user may reach". Every read of another user's
-- data, and every read of club data that does not get its club_id from the
-- ClubMember extractor, goes through these functions (directly in SQL, or
-- through crate::visibility / clubs::extract). Phase 3 adds friendships to
-- bc_can_see_user and bc_visible_owners and nowhere else.
--
-- Set-returning functions are plain SQL with one statement, so the planner
-- inlines them into the calling query (verified with EXPLAIN: no Function Scan).
-- Use them for lists and aggregates: JOIN bc_visible_quotes($1) AS q ON ...
-- Scalar functions are for single checks; they never return NULL.
-- sqlx infers every column of a function result as nullable: use `AS "x!"`.
-- A migration that adds a column to shelf_entries, quotes or posts must update
-- the matching function below if callers need the column.
------------------------------------------------------------------------------

-- Clubs the viewer belongs to, with role. For club data reached by a global id
-- or a query parameter (feeds, /api/posts/{id}, club_picks on books).
CREATE FUNCTION bc_member_clubs(viewer bigint) RETURNS TABLE (club_id bigint, role text, joined_at timestamptz)
    LANGUAGE sql STABLE PARALLEL SAFE
    BEGIN ATOMIC
        SELECT m.club_id, m.role, m.joined_at
        FROM club_memberships AS m
        WHERE m.user_id = viewer;
    END;

CREATE FUNCTION bc_is_member(viewer bigint, club bigint) RETURNS boolean
    LANGUAGE sql STABLE PARALLEL SAFE
    RETURN EXISTS (SELECT 1 FROM club_memberships AS m WHERE m.user_id = viewer AND m.club_id = club);

-- True when `viewer` may see `owner`'s personal data: same user, or the two
-- share at least one club. (Phase 3: OR they are friends.) Never NULL: an
-- unknown or NULL owner (a deleted account) gives false.
CREATE FUNCTION bc_can_see_user(viewer bigint, owner bigint) RETURNS boolean
    LANGUAGE sql STABLE PARALLEL SAFE
    RETURN coalesce(viewer = owner, false) OR EXISTS (
        SELECT 1
        FROM club_memberships AS a
        JOIN club_memberships AS b ON b.club_id = a.club_id
        WHERE a.user_id = viewer AND b.user_id = owner
    );

-- Per-item rule for diary roots, quotes and ratings: the owner always sees the
-- item; others only when it is not only_me and they are in the audience.
CREATE FUNCTION bc_can_see_item(viewer bigint, owner bigint, visibility text) RETURNS boolean
    LANGUAGE sql STABLE PARALLEL SAFE
    RETURN coalesce(viewer = owner OR (visibility = 'audience' AND bc_can_see_user(viewer, owner)), false);

-- Everyone whose personal data `viewer` may see, INCLUDING the viewer
-- (is_self = true). Lists of "other readers" add WHERE NOT is_self.
CREATE FUNCTION bc_visible_owners(viewer bigint) RETURNS TABLE (user_id bigint, is_self boolean)
    LANGUAGE sql STABLE PARALLEL SAFE
    BEGIN ATOMIC
        SELECT viewer, true
        UNION ALL
        SELECT DISTINCT b.user_id, false
        FROM club_memberships AS a
        JOIN club_memberships AS b ON b.club_id = a.club_id
        WHERE a.user_id = viewer AND b.user_id <> viewer;
    END;

-- Shelf entries the viewer may see, with the rating rule already applied:
-- for someone else's only_me entry, rating is NULL, take is '' and
-- rating_visibility is NULL. dnf_reason and progress are shelf state and stay.
-- Every reader list, rating mean, rating count, stat and overlap over other
-- users' shelves reads through this function.
CREATE FUNCTION bc_visible_shelf(viewer bigint) RETURNS TABLE (
    id bigint, user_id bigint, work_id bigint, edition_id bigint, status text,
    "position" integer, shelf_position integer, rating integer, rating_visibility text,
    take text, dnf_reason text, progress integer, updated_at timestamptz,
    started_at timestamptz, finished_at timestamptz, is_self boolean)
    LANGUAGE sql STABLE PARALLEL SAFE
    BEGIN ATOMIC
        SELECT s.id, s.user_id, s.work_id, s.edition_id, s.status::text,
               s."position", s.shelf_position,
               CASE WHEN o.is_self OR s.rating_visibility = 'audience' THEN s.rating END,
               CASE WHEN o.is_self THEN s.rating_visibility END,
               CASE WHEN o.is_self OR s.rating_visibility = 'audience' THEN s.take ELSE '' END,
               s.dnf_reason, s.progress, s.updated_at, s.started_at, s.finished_at, o.is_self
        FROM shelf_entries AS s
        JOIN bc_visible_owners(viewer) AS o ON o.user_id = s.user_id;
    END;

-- Quotes the viewer may see: their own, plus audience quotes of their audience.
-- quote_count and every stats quote count read through this function, so other
-- users' only_me quotes are never counted.
CREATE FUNCTION bc_visible_quotes(viewer bigint) RETURNS TABLE (
    id bigint, user_id bigint, work_id bigint, edition_id bigint, body text, page integer,
    visibility text, created_at timestamptz, updated_at timestamptz, is_self boolean)
    LANGUAGE sql STABLE PARALLEL SAFE
    BEGIN ATOMIC
        SELECT q.id, q.user_id, q.work_id, q.edition_id, q.body, q.page, q.visibility,
               q.created_at, q.updated_at, o.is_self
        FROM quotes AS q
        JOIN bc_visible_owners(viewer) AS o ON o.user_id = q.user_id
        WHERE o.is_self OR q.visibility = 'audience';
    END;

-- Ids of the posts (both scopes, tombstones included) the viewer may see:
--   * club posts and their replies: members of that club;
--   * diary roots: bc_can_see_item(viewer, author, visibility); a root whose
--     author account was deleted (author_id NULL, always a tombstone) is visible
--     to whoever can see the author of at least one of its replies, unless the
--     author had made it only_me;
--   * diary replies: the root is visible, and the viewer is the root's author or
--     can see the reply's author.
-- Feeds add `deleted_at IS NULL`; threads keep tombstones as anchors.
CREATE FUNCTION bc_visible_posts(viewer bigint) RETURNS TABLE (id bigint)
    LANGUAGE sql STABLE PARALLEL SAFE
    BEGIN ATOMIC
        SELECT p.id
        FROM posts AS p
        JOIN club_memberships AS m ON m.club_id = p.club_id AND m.user_id = viewer
        UNION ALL
        SELECT p.id
        FROM posts AS p
        WHERE p.club_id IS NULL AND p.parent_id IS NULL
          AND ((p.author_id IN (SELECT o.user_id FROM bc_visible_owners(viewer) AS o)
                AND (p.author_id = viewer OR p.visibility = 'audience'))
               OR (p.author_id IS NULL AND p.visibility = 'audience' AND EXISTS (
                       SELECT 1
                       FROM posts AS r
                       JOIN bc_visible_owners(viewer) AS o ON o.user_id = r.author_id
                       WHERE r.parent_id = p.id)))
        UNION ALL
        SELECT r.id
        FROM posts AS r
        JOIN posts AS p ON p.id = r.parent_id
        WHERE r.club_id IS NULL
          AND (p.author_id = viewer
               OR (r.author_id IN (SELECT o.user_id FROM bc_visible_owners(viewer) AS o)
                   AND p.visibility = 'audience'
                   AND (p.author_id IS NULL
                        OR p.author_id IN (SELECT o.user_id FROM bc_visible_owners(viewer) AS o))));
    END;

CREATE FUNCTION bc_can_see_post(viewer bigint, post bigint) RETURNS boolean
    LANGUAGE sql STABLE PARALLEL SAFE
    RETURN EXISTS (SELECT 1 FROM bc_visible_posts(viewer) AS v WHERE v.id = post);
